1	//! Regression coverage for keygen's write/sync contract on Unix: what must
2	//! hold while the 32 key bytes are being saved, and when saving cannot
3	//! complete (see README "文件权限" for the permission side, covered in
4	//! keygen_permissions.rs).
5	//!
6	//! What is protected here:
7	//!
8	//! * Partial writes: if the kernel only accepts part of the buffer per
9	//!   write() call, the remaining bytes still land -- no byte already written
10	//!   is duplicated, no later byte is skipped. The final file is exactly the
11	//!   32 raw key bytes (no newline, header, or trailer), mode 0600.
12	//! * Recoverable interruption: write() failing with EINTR and then
13	//!   succeeding still completes the same generation with exit code 0.
14	//! * Success is only reported after every byte is written *and* fsynced:
15	//!   exit 0, the usual "Key saved to ..." line on stdout, empty stderr.
16	//! * Unrecoverable write error after some bytes landed, and fsync failure
17	//!   after all bytes landed: exit 1, stderr explains the failure (naming
18	//!   the target), stdout carries no success message, the file created by
19	//!   this invocation is removed, and neither the parent directory's
20	//!   permissions nor pre-existing siblings are touched. Key bytes never
21	//!   appear on stdout/stderr, on success or on failure.
22	//!
23	//! The faults are injected by the LD_PRELOAD shim (tests/support/permfail),
24	//! which also traces every write()/fsync() on the key descriptor so the
25	//! byte stream can be checked for gaps, duplicates, and leaks.
26	#![cfg(unix)]
27	
28	use std::collections::HashMap;
29	use std::fs;
30	use std::os::unix::fs::{MetadataExt, PermissionsExt};
31	use std::path::{Path, PathBuf};
32	use std::process::Command;
33	use std::sync::atomic::{AtomicU64, Ordering};
34	
35	const KEY_LEN: usize = 32;
36	const MODE_0600: u32 = 0o600;
37	const UMASKS: [u32; 3] = [0o022, 0o000, 0o777];
38	
39	fn bin() -> PathBuf {
40	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
41	}
42	
43	fn permfail_so() -> Option<PathBuf> {
44	    option_env!("WRAPFILE_PERMFAIL_SO").map(PathBuf::from)
45	}
46	
47	// ---------------------------------------------------------------------------
48	// scratch directory
49	// ---------------------------------------------------------------------------
50	
51	struct Tmp {
52	    path: PathBuf,
53	}
54	
55	impl Tmp {
56	    fn new(label: &str) -> Tmp {
57	        static SEQ: AtomicU64 = AtomicU64::new(0);
58	        let path = std::env::temp_dir().join(format!(
59	            "wrapfile-keygen-write-tests-{}-{}-{}",
60	            std::process::id(),
61	            label,
62	            SEQ.fetch_add(1, Ordering::Relaxed)
63	        ));
64	        fs::create_dir_all(&path).unwrap();
65	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
66	        Tmp { path }
67	    }
68	
69	    fn child(&self, name: impl AsRef<Path>) -> PathBuf {
70	        self.path.join(name)
71	    }
72	}
73	
74	impl Drop for Tmp {
75	    fn drop(&mut self) {
76	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
77	        let _ = fs::remove_dir_all(&self.path);
78	    }
79	}
80	
81	// ---------------------------------------------------------------------------
82	// running the binary
83	// ---------------------------------------------------------------------------
84	
85	struct Run {
86	    rc: i32,
87	    out: Vec<u8>,
88	    err: Vec<u8>,
89	}
90	
91	/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
92	/// wrapper, with the permfail shim preloaded and a trace file configured.
93	fn run_keygen(key: &Path, umask: u32, so: &Path, extra_env: &[(&str, &str)], trace: &Path) -> Run {
94	    let mut cmd = Command::new("/bin/sh");
95	    cmd.arg("-c")
96	        .arg(format!("umask {umask:04o}; exec \"$@\""))
97	        .arg("sh")
98	        .arg(bin())
99	        .arg("keygen")
100	        .arg(key)
101	        .env("LD_PRELOAD", so)
102	        .env("WRAPFILE_TEST_TRACE_FILE", trace);
103	    for (k, v) in extra_env {
104	        cmd.env(k, v);
105	    }
106	    let o = cmd.output().unwrap();
107	    Run {
108	        rc: o.status.code().unwrap_or(-1),
109	        out: o.stdout,
110	        err: o.stderr,
111	    }
112	}
113	
114	// ---------------------------------------------------------------------------
115	// shim trace log
116	// ---------------------------------------------------------------------------
117	
118	struct Event {
119	    kind: String,
120	    attrs: HashMap<String, String>,
121	}
122	
123	impl Event {
124	    fn get(&self, key: &str) -> Option<&str> {
125	        self.attrs.get(key).map(String::as_str)
126	    }
127	
128	    fn ret(&self) -> Option<i64> {
129	        self.get("ret").and_then(|v| v.parse().ok())
130	    }
131	
132	    fn off(&self) -> Option<u64> {
133	        self.get("off").and_then(|v| v.parse().ok())
134	    }
135	
136	    fn hex_bytes(&self) -> Option<Vec<u8>> {
137	        let hex = self.get("hex")?;
138	        assert_eq!(hex.len() % 2, 0, "odd hex in trace line");
139	        Some(
140	            (0..hex.len() / 2)
141	                .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
142	                .collect(),
143	        )
144	    }
145	}
146	
147	fn parse_trace(path: &Path) -> Vec<Event> {
148	    let text = fs::read_to_string(path).unwrap();
149	    text.lines()
150	        .map(|line| {
151	            let mut it = line.split_whitespace();
152	            let kind = it.next().unwrap_or("").to_string();
153	            let attrs = it
154	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
155	                .collect();
156	            Event { kind, attrs }
157	        })
158	        .collect()
159	}
160	
161	/// Create the trace file up front (mode 0644) so that it stays readable even
162	/// when the child runs under umask 0777 -- the shim opens it O_APPEND.
163	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
164	    let p = dir.join(name);
165	    fs::File::create(&p).unwrap();
166	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
167	    p
168	}
169	
170	/// The successful write() calls, in call order: (offset, bytes landed, bytes).
171	fn successful_writes(events: &[Event]) -> Vec<(u64, u64, Option<Vec<u8>>)> {
172	    events
173	        .iter()
174	        .filter(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
175	        .map(|e| {
176	            (
177	                e.off().expect("WRITE event needs off="),
178	                e.ret().unwrap() as u64,
179	                e.hex_bytes(),
180	            )
181	        })
182	        .collect()
183	}
184	
185	/// The landed writes must tile [0, total) exactly: the first starts at 0,
186	/// each continues where the previous ended -- no byte written twice, none
187	/// skipped.
188	fn assert_writes_tile(writes: &[(u64, u64, Option<Vec<u8>>)], total: usize, context: &str) {
189	    assert!(!writes.is_empty(), "{context}: no bytes were ever written");
190	    let mut expect = 0u64;
191	    for (off, n, _) in writes {
192	        assert_eq!(
193	            *off, expect,
194	            "{context}: write at offset {off} overlaps or leaves a gap (expected {expect})"
195	        );
196	        expect += n;
197	    }
198	    assert_eq!(
199	        expect as usize, total,
200	        "{context}: writes must add up to exactly {total} bytes, got {expect}"
201	    );
202	}
203	
204	fn reconstruct(writes: &[(u64, u64, Option<Vec<u8>>)]) -> Vec<u8> {
205	    writes
206	        .iter()
207	        .flat_map(|(_, _, hex)| hex.clone().expect("TRACE_BYTES must be on"))
208	        .collect()
209	}
210	
211	// ---------------------------------------------------------------------------
212	// filesystem assertions
213	// ---------------------------------------------------------------------------
214	
215	fn mode_of(path: &Path) -> u32 {
216	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
217	}
218	
219	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
220	    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
221	}
222	
223	/// The full success contract: exit 0, empty stderr, only the save-location
224	/// line on stdout, and exactly 32 raw key bytes in a 0600 file that leaks
225	/// nowhere.
226	fn assert_success(key: &Path, run: &Run) -> Vec<u8> {
227	    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
228	    assert!(
229	        run.err.is_empty(),
230	        "stderr must be empty on success, got {}",
231	        String::from_utf8_lossy(&run.err)
232	    );
233	    assert_eq!(
234	        run.out,
235	        format!("Key saved to {}\n", key.display()).into_bytes(),
236	        "stdout must be exactly the save-location message"
237	    );
238	
239	    let meta = fs::metadata(key).expect("key file must exist on success");
240	    assert_eq!(meta.len() as usize, KEY_LEN, "key must be exactly 32 bytes");
241	    assert_eq!(
242	        meta.mode() & 0o7777,
243	        MODE_0600,
244	        "key file mode must be exactly 0600"
245	    );
246	
247	    let bytes = fs::read(key).unwrap();
248	    assert_eq!(bytes.len(), KEY_LEN);
249	    assert!(bytes.iter().any(|&b| b != 0), "key must not be all zeroes");
250	    assert!(
251	        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
252	        "key bytes must never appear on stdout/stderr"
253	    );
254	    bytes
255	}
256	
257	/// The failure contract shared by the write-error and fsync-error tests:
258	/// exit 1, an explanation on stderr, no success output, no leaked key
259	/// material, and no trace of this invocation left in the parent directory.
260	fn assert_failed_cleanly(
261	    key: &Path,
262	    run: &Run,
263	    dir: &Path,
264	    allowed_entries: &[&str],
265	    leaked_candidate: &[u8],
266	) {
267	    assert_eq!(run.rc, 1, "an unfinishable save must exit 1");
268	    assert!(
269	        run.out.is_empty(),
270	        "no success message may be printed on failure, got {}",
271	        String::from_utf8_lossy(&run.out)
272	    );
273	    assert!(!run.err.is_empty(), "stderr must explain the failure");
274	    let stderr = String::from_utf8_lossy(&run.err);
275	    assert!(
276	        stderr.contains(&key.display().to_string()),
277	        "stderr should name the target path, got: {stderr}"
278	    );
279	    assert!(
280	        !contains_slice(&run.out, leaked_candidate)
281	            && !contains_slice(&run.err, leaked_candidate),
282	        "key material must never leak to stdout/stderr, even on failure"
283	    );
284	
285	    assert!(
286	        !key.exists(),
287	        "the file this invocation created must be removed after the failure"
288	    );
289	    let mut leftovers: Vec<String> = fs::read_dir(dir)
290	        .unwrap()
291	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
292	        .filter(|n| !allowed_entries.contains(&n.as_str()))
293	        .collect();
294	    leftovers.sort();
295	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
296	}
297	
298	// A pre-existing object that must survive a failed keygen byte-for-byte.
299	struct Sentinel {
300	    path: PathBuf,
301	    bytes: Vec<u8>,
302	    mode: u32,
303	    inode: u64,
304	}
305	
306	impl Sentinel {
307	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
308	        let path = dir.join(name);
309	        fs::write(&path, bytes).unwrap();
310	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
311	        let meta = fs::metadata(&path).unwrap();
312	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
313	    }
314	
315	    fn assert_untouched(&self) {
316	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
317	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
318	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
319	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
320	    }
321	}
322	
323	// ---------------------------------------------------------------------------
324	// tests
325	// ---------------------------------------------------------------------------
326	
327	#[test]
328	fn partial_writes_save_the_full_key_exactly_once() {
329	    let Some(so) = permfail_so() else {
330	        eprintln!("skipping: permfail shim not available on this target");
331	        return;
332	    };
333	
334	    for umask in UMASKS {
335	        let tmp = Tmp::new("partial");
336	        let key = tmp.child("key");
337	        let trace = prepare_trace(&tmp.path, "trace.log");
338	
339	        // The kernel accepts only one byte per write() call.
340	        let run = run_keygen(
341	            &key,
342	            umask,
343	            &so,
344	            &[
345	                ("WRAPFILE_TEST_PARTIAL_WRITE", "1"),
346	                ("WRAPFILE_TEST_TRACE_BYTES", "1"),
347	            ],
348	            &trace,
349	        );
350	
351	        let on_disk = assert_success(&key, &run);
352	
353	        let events = parse_trace(&trace);
354	        let writes = successful_writes(&events);
355	        assert!(
356	            writes.len() >= KEY_LEN,
357	            "one-byte writes should mean at least 32 write() calls, got {}",
358	            writes.len()
359	        );
360	        // No written byte repeated, no later byte dropped...
361	        assert_writes_tile(&writes, KEY_LEN, "partial writes");
362	        // ...and the bytes the program handed to the kernel are exactly the
363	        // bytes that ended up in the file -- nothing reordered or invented.
364	        assert_eq!(
365	            reconstruct(&writes),
366	            on_disk,
367	            "file content must equal the concatenation of the write() calls"
368	        );
369	
370	        // Success was reported only after the data was synced to disk.
371	        let last_write = events
372	            .iter()
373	            .rposition(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
374	            .unwrap();
375	        let fsynced = events
376	            .iter()
377	            .position(|e| e.kind == "FSYNC" && e.ret() == Some(0))
378	            .expect("the key must be fsynced before success is reported");
379	        assert!(fsynced > last_write, "fsync must follow the last write");
380	    }
381	}
382	
383	#[test]
384	fn interrupted_writes_are_retried_until_the_key_is_saved() {
385	    let Some(so) = permfail_so() else {
386	        eprintln!("skipping: permfail shim not available on this target");
387	        return;
388	    };
389	
390	    let tmp = Tmp::new("eintr");
391	    let key = tmp.child("key");
392	    let trace = prepare_trace(&tmp.path, "trace.log");
393	
394	    // The first five write() calls are interrupted before any byte is
395	    // consumed; afterwards the system recovers (and still only takes three
396	    // bytes at a time). The same generation must complete, not fail.
397	    let run = run_keygen(
398	        &key,
399	        0o022,
400	        &so,
401	        &[
402	            ("WRAPFILE_TEST_WRITE_EINTR", "5"),
403	            ("WRAPFILE_TEST_PARTIAL_WRITE", "3"),
404	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
405	        ],
406	        &trace,
407	    );
408	
409	    let on_disk = assert_success(&key, &run);
410	
411	    let events = parse_trace(&trace);
412	    let eintrs = events
413	        .iter()
414	        .filter(|e| e.kind == "WRITE" && e.get("errno") == Some("EINTR"))
415	        .count();
416	    assert_eq!(eintrs, 5, "all injected EINTRs must have been observed");
417	
418	    // The interruption consumed nothing: the bytes that eventually landed
419	    // still tile [0, 32) exactly once and match the file.
420	    let writes = successful_writes(&events);
421	    assert_writes_tile(&writes, KEY_LEN, "writes after EINTR");
422	    assert_eq!(reconstruct(&writes), on_disk);
423	}
424	
425	#[test]
426	fn unrecoverable_write_error_fails_and_removes_the_partial_file() {
427	    let Some(so) = permfail_so() else {
428	        eprintln!("skipping: permfail shim not available on this target");
429	        return;
430	    };
431	
432	    let tmp = Tmp::new("write-error");
433	    let key = tmp.child("key");
434	    let sibling = Sentinel::file(&tmp.path, "sibling", b"do-not-touch", 0o644);
435	    let parent_mode_before = mode_of(&tmp.path);
436	    let trace = prepare_trace(&tmp.path, "trace.log");
437	
438	    // Ten bytes land (4 + 4 + 2), then every further write fails with EIO.
439	    let run = run_keygen(
440	        &key,
441	        0o022,
442	        &so,
443	        &[
444	            ("WRAPFILE_TEST_PARTIAL_WRITE", "4"),
445	            ("WRAPFILE_TEST_FAIL_WRITE_AFTER", "10"),
446	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
447	        ],
448	        &trace,
449	    );
450	
451	    let events = parse_trace(&trace);
452	    let writes = successful_writes(&events);
453	    // The failure really happened mid-write: part of the key was on disk.
454	    assert_writes_tile(&writes, 10, "writes before the error");
455	    assert!(
456	        events
457	            .iter()
458	            .any(|e| e.kind == "WRITE" && e.get("errno") == Some("EIO")),
459	        "the unrecoverable write error must have been injected"
460	    );
461	    assert!(
462	        events.iter().all(|e| e.kind != "FSYNC"),
463	        "an incomplete key must never be synced as if complete"
464	    );
465	    let partial_key = reconstruct(&writes);
466	    assert_eq!(partial_key.len(), 10);
467	
468	    assert_failed_cleanly(&key, &run, &tmp.path, &["sibling", "trace.log"], &partial_key);
469	    sibling.assert_untouched();
470	    assert_eq!(
471	        mode_of(&tmp.path),
472	        parent_mode_before,
473	        "parent directory permissions must be untouched"
474	    );
475	
476	    // The failure was transient: a retry without the fault saves a full key.
477	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
478	    let run2 = run_keygen(&key, 0o022, &so, &[], &trace2);
479	    assert_success(&key, &run2);
480	    sibling.assert_untouched();
481	}
482	
483	#[test]
484	fn fsync_failure_after_full_write_fails_and_removes_the_file() {
485	    let Some(so) = permfail_so() else {
486	        eprintln!("skipping: permfail shim not available on this target");
487	        return;
488	    };
489	
490	    let tmp = Tmp::new("fsync-error");
491	    let key = tmp.child("key");
492	    let sibling = Sentinel::file(&tmp.path, "sibling", b"keep-me", 0o600);
493	    let parent_mode_before = mode_of(&tmp.path);
494	    let trace = prepare_trace(&tmp.path, "trace.log");
495	
496	    // All 32 bytes are written, but syncing them to disk fails.
497	    let run = run_keygen(
498	        &key,
499	        0o022,
500	        &so,
501	        &[
502	            ("WRAPFILE_TEST_FAIL_FSYNC", "1"),
503	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
504	        ],
505	        &trace,
506	    );
507	
508	    let events = parse_trace(&trace);
509	    let writes = successful_writes(&events);
510	    // The whole key was written before the sync failed...
511	    assert_writes_tile(&writes, KEY_LEN, "writes before fsync");
512	    assert!(
513	        events
514	            .iter()
515	            .any(|e| e.kind == "FSYNC" && e.ret() == Some(-1)),
516	        "the fsync failure must have been injected"
517	    );
518	    // ...so the full key is the material that must not leak.
519	    let full_key = reconstruct(&writes);
520	    assert_eq!(full_key.len(), KEY_LEN);
521	
522	    assert_failed_cleanly(&key, &run, &tmp.path, &["sibling", "trace.log"], &full_key);
523	    sibling.assert_untouched();
524	    assert_eq!(
525	        mode_of(&tmp.path),
526	        parent_mode_before,
527	        "parent directory permissions must be untouched"
528	    );
529	}
