1	/*
2	 * permfail.c -- LD_PRELOAD shim for wrapfile keygen permission tests.
3	 *
4	 * Two jobs:
5	 *
6	 * 1. Tracing. For the file the guest creates with open(O_CREAT|...) it logs
7	 *    to WRAPFILE_TEST_TRACE_FILE (one line per event):
8	 *
9	 *      BORN        fd=N mode=0oNNNN   mode right after the creating open()
10	 *      FCHMOD      ret=0/-1 mode=0oNNNN
11	 *      FSTAT       ret=0/-1 mode=0oNNNN size=N   (mode reported to guest)
12	 *      FIRST_WRITE mode=0oNNNN size=N  immediately before the first write()
13	 *      WRITE       off=N req=N ret=N [hex=...]   each write() on the key fd;
14	 *                    ret=-1 errno=ENAME for injected faults
15	 *      FSYNC       ret=0/-1
16	 *
17	 *    FIRST_WRITE with mode=0o600 and size=0 proves the program had both set
18	 *    and *confirmed* 0600 before a single key byte was written. The WRITE
19	 *    stream (off ascending from 0 with no gaps or overlaps, ending at 32)
20	 *    proves partial writes were resumed without duplicating or dropping
21	 *    bytes, and FSYNC ret=0 after the last WRITE proves the key was synced
22	 *    to disk before the program reported success.
23	 *
24	 * 2. Fault injection (only for a descriptor the guest itself created):
25	 *      WRAPFILE_TEST_FAIL_FCHMOD=1      fchmod() fails with EPERM
26	 *      WRAPFILE_TEST_FAIL_FSTAT=1       fstat()/fstat64() fail (EBADF), so the
27	 *                                        resulting mode cannot be confirmed
28	 *      WRAPFILE_TEST_LIE_MODE=OCTAL     fstat reports these low 12 mode bits
29	 *                                        (e.g. 0000) while the real fchmod
30	 *                                        succeeded -- a filesystem that silently
31	 *                                        stores another mode
32	 *      WRAPFILE_TEST_PARTIAL_WRITE=N    write() accepts at most N bytes per
33	 *                                        call (a kernel that only takes part
34	 *                                        of the buffer)
35	 *      WRAPFILE_TEST_WRITE_EINTR=N      the first N write() calls fail with
36	 *                                        EINTR, then writes succeed normally
37	 *      WRAPFILE_TEST_FAIL_WRITE_AFTER=N after N bytes in total have landed,
38	 *                                        write() fails with EIO (the last
39	 *                                        partial write is clamped so exactly
40	 *                                        N bytes are on disk before the error)
41	 *      WRAPFILE_TEST_FAIL_FSYNC=1       fsync() fails with EIO
42	 *      WRAPFILE_TEST_TRACE_BYTES=1      append hex=... of the bytes each
43	 *                                        write() actually landed, so tests can
44	 *                                        reconstruct the byte stream and check
45	 *                                        nothing secret leaks to stdout/stderr
46	 *
47	 * The shim only activates inside an executable whose basename starts with
48	 * "wrapfile" (checked via /proc/self/exe), so a wrapper shell used to set
49	 * the umask is never affected. After execve() the guest starts with a fresh
50	 * table, so only the guest's own O_CREAT descriptor (the key file) is
51	 * tracked; stdout/stderr and unrelated fds pass through untouched.
52	 */
