363	        return real_fstat64(fd, st);
364	    return handle_fstat(fd, st, 1);
365	}
366	
367	ssize_t write(int fd, const void *buf, size_t count)
368	{
369	    if (!real_write)
370	        real_write = (write_fn)dlsym(RTLD_NEXT, "write");
371	
372	    if (!process_active() || !is_tracked(fd))
373	        return real_write(fd, buf, count);
374	    load_config();
375	
376	    if (!written[fd]) {
377	        written[fd] = 1;
378	        struct stat st;
379	        fstat_fn fn = get_real_fstat();
380	        if (fn && fn(fd, &st) == 0) {
381	            trace("FIRST_WRITE mode=0%04o size=%lld\n",
382	                  (unsigned)(st.st_mode & 07777),
383	                  (long long)st.st_size);
384	        } else {
385	            trace("FIRST_WRITE mode=unknown size=unknown\n");
386	        }
387	    }
388	
389	    /* A recoverable interruption: the call fails before any byte is
390	     * consumed, and the next call succeeds. */
391	    if (eintr_left[fd] > 0) {
392	        eintr_left[fd]--;
393	        trace("WRITE ret=-1 errno=EINTR\n");
394	        errno = EINTR;
395	        return -1;
396	    }
397	
398	    /* A kernel that only accepts part of the buffer per call. */
399	    size_t allowed = count;
400	    if (cfg_partial_write > 0 && allowed > (size_t)cfg_partial_write)
401	        allowed = (size_t)cfg_partial_write;
402	
403	    /* An unrecoverable error once N bytes have landed. */
404	    if (cfg_fail_write_after >= 0) {
405	        long long remaining =
406	            (long long)cfg_fail_write_after - (long long)written_total[fd];
407	        if (remaining <= 0) {
408	            trace("WRITE ret=-1 errno=EIO off=%llu\n", written_total[fd]);
409	            errno = EIO;
410	            return -1;
411	        }
412	        if (allowed > (size_t)remaining)
413	            allowed = (size_t)remaining;
414	    }
415	
416	    ssize_t r = real_write(fd, buf, allowed);
417	    if (r > 0) {
418	        unsigned long long off = written_total[fd];
419	        written_total[fd] += (unsigned long long)r;
420	        if (cfg_trace_bytes) {
421	            char *hex = malloc((size_t)r * 2 + 1);
422	            if (hex) {
423	                static const char digits[] = "0123456789abcdef";
424	                const unsigned char *p = buf;
425	                for (ssize_t i = 0; i < r; i++) {
426	                    hex[i * 2] = digits[p[i] >> 4];
427	                    hex[i * 2 + 1] = digits[p[i] & 0xf];
428	                }
429	                hex[r * 2] = '\0';
430	                trace("WRITE off=%llu req=%zu ret=%zd hex=%s\n",
431	                      off, allowed, r, hex);
432	                free(hex);
433	            } else {
434	                trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
435	            }
436	        } else {
437	            trace("WRITE off=%llu req=%zu ret=%zd\n", off, allowed, r);
438	        }
439	    } else {
440	        trace("WRITE off=%llu req=%zu ret=%zd\n",
441	              written_total[fd], allowed, r);
442	    }
443	    return r;
444	}
445	
446	int fsync(int fd)
447	{
448	    if (!real_fsync)
449	        real_fsync = (fsync_fn)dlsym(RTLD_NEXT, "fsync");
