329	#[test]
330	fn permissions_set_and_confirmed_before_any_key_byte() {
331	    let Some(so) = permfail_so() else {
332	        eprintln!("skipping: permfail shim not available on this target");
333	        return;
334	    };
335	
336	    for umask in UMASKS {
337	        let tmp = Tmp::new("before-write");
338	        let key = tmp.child("key");
339	        let trace = prepare_trace(&tmp.path, "trace.log");
340	
341	        let run = run_keygen(&key, umask, Some(&so), &[], Some(&trace));
342	        assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
343	        let events = parse_trace(&trace);
344	
345	        let first_write = first_index(&events, |e| e.kind == "FIRST_WRITE")
346	            .expect("the key must eventually be written");
347	        let w = &events[first_write];
348	
349	        // Immediately before the first write call: mode is exactly 0600 and
350	        // size is still 0 -- no key byte preceded the confirmation.
351	        assert_eq!(w.mode().unwrap(), MODE_0600,
352	            "mode at first write must be exactly 0600 (umask {umask:04o})");
353	        assert_eq!(w.size().unwrap(), 0,
354	            "file must be empty when 0600 is confirmed (umask {umask:04o})");
355	
356	        // fchmod set 0600 and an fstat confirmed it, both before the write.
357	        let chmod = first_index(&events, |e| {
358	            e.kind == "FCHMOD" && e.ret() == Some(0) && e.mode() == Some(MODE_0600)
359	        }).expect("fchmod(fd, 0600) must succeed");
360	        let confirm = first_index(&events, |e| {
361	            e.kind == "FSTAT"
362	                && e.ret() == Some(0)
363	                && e.mode() == Some(MODE_0600)
364	                && e.size() == Some(0)
365	        }).expect("an fstat must confirm exactly 0600 on an empty file");
366	        assert!(chmod < first_write, "fchmod must precede the first write");
367	        assert!(confirm < first_write, "confirmation must precede the first write");
368	
369	        // Every mode observation before the first write (birth included)
370	        // carries no group or other bits: the secret is never exposed while
371	        // open, even for an instant.
372	        for e in events.iter().take(first_write) {
373	            if e.kind == "BORN" || e.kind == "FSTAT" {
374	                if let Some(m) = e.mode() {
375	                    assert_eq!(m & 0o077, 0,
376	                        "group/other bits observed before write in event {}: {:04o}", e.index, m);
377	                }
378	            }
379	        }
380	
381	        // Final on-disk state matches what the trace promised.
382	        assert_eq!(mode_of(&key), MODE_0600);
383	        assert_eq!(fs::metadata(&key).unwrap().len() as usize, KEY_LEN);
384	    }
385	}
