465	#[test]
466	fn existing_objects_are_never_modified() {
467	    // No shim needed: the target already exists, so creation must fail.
468	    for umask in UMASKS {
469	        // --- pre-existing regular file with a non-0600 mode and contents ---
470	        let tmp = Tmp::new("existing-file");
471	        let secret = b"pre-existing-key-material";
472	        let existing = Sentinel::file(&tmp.path, "key", secret, 0o640);
473	        let run = run_keygen(&existing.path, umask, None, &[], None);
474	        assert_eq!(run.rc, 1);
475	        assert!(run.out.is_empty());
476	        existing.assert_untouched();
477	
478	        // --- pre-existing directory ---
479	        let tmp = Tmp::new("existing-dir");
480	        let dir = tmp.child("adir");
481	        fs::create_dir(&dir).unwrap();
482	        fs::set_permissions(&dir, fs::Permissions::from_mode(0o755)).unwrap();
483	        let run = run_keygen(&dir, umask, None, &[], None);
484	        assert_eq!(run.rc, 1);
485	        assert!(run.out.is_empty());
486	        assert!(dir.is_dir());
487	        assert_eq!(mode_of(&dir), 0o755, "existing directory mode must not change");
488	
489	        // --- dangling symlink: never followed, never replaced ---
490	        let tmp = Tmp::new("dangling-symlink");
491	        let target = tmp.child("does-not-exist");
492	        let link = tmp.child("link");
493	        std::os::unix::fs::symlink(&target, &link).unwrap();
494	        let run = run_keygen(&link, umask, None, &[], None);
495	        assert_eq!(run.rc, 1);
496	        assert!(run.out.is_empty());
497	        let md = fs::symlink_metadata(&link).expect("symlink itself must remain");
498	        assert!(md.file_type().is_symlink(), "dangling symlink must not be replaced");
499	        assert_eq!(fs::read_link(&link).unwrap(), target);
500	        assert!(!target.exists(), "must not create the symlink target through the link");
501	
502	        // --- missing parent directory: not auto-created ---
503	        let tmp = Tmp::new("missing-parent");
504	        let key = tmp.child("missing/sub/key");
505	        let run = run_keygen(&key, umask, None, &[], None);
506	        assert_eq!(run.rc, 1);
507	        assert!(run.out.is_empty());
508	        assert!(!tmp.child("missing").exists(), "parent directories must not be created");
509	    }
